// ─── Utility helpers ────────────────────────────────────────────────
function rand(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function pick(arr) { return arr[rand(0, arr.length - 1)]; }
function shuffle(arr) { return [...arr].sort(() => Math.random() - 0.5); }
function rating() { return (4 + Math.random() * 0.9).toFixed(1); }
function reviews() { return rand(50, 500); }
function stock() { return rand(10, 200); }
function sold() { return rand(0, 500); }
function isNew(idx, total, pct = 0.2) { return idx < Math.floor(total * pct); }
function freeShipping(price) { return price >= 5000; }
function img(photoId, w = 1200) {
  return `https://images.unsplash.com/photo-${photoId}?q=80&w=${w}&auto=format&fit=crop`;
}

