// ─── Product generation ─────────────────────────────────────────────
function generateProducts(categoryName, defs, startIndex = 0) {
  const products = [];
  let idx = startIndex;
  for (const def of defs) {
    const count = def.names.length;
    for (let i = 0; i < count; i++) {
      const photoId = pick(def.img);
      const price = rand(def.prices[0], def.prices[1]);
      const colorKey = pick(def.colors);
      const product = {
        id: `${categoryName.toLowerCase()}-${idx}`,
        name: def.names[i],
        description: def.desc(def.names[i]),
        price,
        category: categoryName,
        image: img(photoId),
        sizes: def.sizes,
        colors: COLORS[colorKey] || COLORS.neutral,
        isNew: isNew(idx, defs.reduce((s, d) => s + d.names.length, 0)),
        rating: rating(),
        reviews: reviews(),
        stock: stock(),
        sold: sold(),
        freeShipping: freeShipping(price),
        shippingFrom: "Nepal",
        tags: def.tags || [categoryName.toLowerCase(), def.slug],
      };
      products.push(product);
      idx++;
    }
  }
  return products;
}

// ─── Generate all categories ────────────────────────────────────────
const allProducts = [];
const categoryKeys = Object.keys(catalogDefs);
let globalIdx = 0;

for (const cat of categoryKeys) {
  const products = generateProducts(cat, catalogDefs[cat], globalIdx);
  allProducts.push(...products);
  globalIdx += products.length;
  console.log(`  ${cat}: ${products.length} products`);
}

console.log(`\nTotal products generated: ${allProducts.length}`);

// ─── Write products.json ────────────────────────────────────────────
const publicDir = path.join(__dirname, "public");
if (!fs.existsSync(publicDir)) fs.mkdirSync(publicDir, { recursive: true });
fs.writeFileSync(path.join(publicDir, "products.json"), JSON.stringify(allProducts, null, 2));
console.log(`Wrote public/products.json`);

