const marketplaceProducts = marketplaceDefs.map((m, i) => {
  const price = m.price + rand(-200, 500);
  return {
    id: `marketplace-${i}`,
    name: m.name,
    description: m.desc,
    price: Math.max(200, price),
    category: m.cat,
    image: img(m.img),
    sizes: m.sizes,
    colors: COLORS.neutral,
    isNew: i < Math.floor(marketplaceDefs.length * 0.2),
    rating: rating(),
    reviews: reviews(),
    stock: stock(),
    sold: sold(),
    freeShipping: freeShipping(price),
    shippingFrom: "Nepal",
    tags: m.tags,
  };
});

fs.writeFileSync(path.join(publicDir, "marketplace.json"), JSON.stringify(marketplaceProducts, null, 2));
console.log(`Wrote public/marketplace.json (${marketplaceProducts.length} products)`);

