console.log(`marketplace.json: ${marketplaceProducts.length} products`);
console.log(`TOTAL:            ${allProducts.length + traditionalProducts.length + marketplaceProducts.length} products`);

const categoryCounts = {};
allProducts.forEach(p => { categoryCounts[p.category] = (categoryCounts[p.category] || 0) + 1; });
console.log("\nCategory breakdown (products.json):");
Object.entries(categoryCounts).forEach(([cat, count]) => {
  console.log(`  ${cat}: ${count}`);
});
